# Run Tests -- PowerShell wrapper for the deployment-verification suite.
# Auto-generated by datrix-codegen-java. Do not edit manually.
#
# Usage:
#   ./deployment-tests/run-tests.ps1              # compose up, run deployment tests, compose down
#   ./deployment-tests/run-tests.ps1 -NoDown       # leave the compose stack running afterward
#   ./deployment-tests/run-tests.ps1 -NoUp         # assume the stack is already up

param(
    [switch]$NoUp,
    [switch]$NoDown
)

$ErrorActionPreference = "Stop"
$ComposeProject = "ecommerce_test"

if (-not $NoUp) {
    Write-Host "Starting compose stack '$ComposeProject'..." -ForegroundColor Cyan
    docker compose -p $ComposeProject up -d --build
    if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
}

try {
    Write-Host "Running deployment tests..." -ForegroundColor Cyan
    Push-Location "deployment-tests"
    try {
        ./mvnw test -Dtest=DeploymentTest
        $testExitCode = $LASTEXITCODE
    } finally {
        Pop-Location
    }

    # Live-component tests (JUnit tags 'spec'/'integration') live in the SERVICE
    # modules and are excluded from every plain `mvnw test` by the generated
    # pom's datrix.surefire.excludedGroups. The stack is up right now, so this
    # is the phase that runs them -- overriding that property to empty and
    # selecting the tags explicitly. failIfNoTests=false keeps a service that
    # declares none from failing the run.
    $LiveComponentModules = @(
        "ecommerce_user_service",
        "ecommerce_product_service",
        "ecommerce_order_service",
        "ecommerce_payment_service",
        "ecommerce_shipping_service",
        "ecommerce_notification_service"
    )
    foreach ($module in $LiveComponentModules) {
        Write-Host "Running live-component tests for '$module'..." -ForegroundColor Cyan
        Push-Location $module
        try {
            ./mvnw test -Dgroups=spec,integration "-Ddatrix.surefire.excludedGroups=" -DfailIfNoTests=false
            if ($LASTEXITCODE -ne 0) { $testExitCode = $LASTEXITCODE }
        } finally {
            Pop-Location
        }
    }
} finally {
    if (-not $NoDown) {
        Write-Host "Stopping compose stack '$ComposeProject'..." -ForegroundColor Cyan
        docker compose -p $ComposeProject down
    }
}

if ($testExitCode -ne 0) { exit $testExitCode }
